ee:message.ee:set-payload:
%dw 2.0
output application/json

var fechaActual = {
        "\$date": (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
    }

---

{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
  "query" : {
    "insert": "MDM_CD_SERVICIO",
    "documents": [
		      {

		  "Fecha_Creacion": fechaActual,
		  "Usuario_Creacion": "",
		  "Fecha_Modificacion": null,
		  "Usuario_Modificacion":"",
		  "Id_Cuenta_Servicio": vars.resultadoProductos.Servicio_Tramite.Id_Cuenta_Servicio,
		  "Bundle": vars.resultadoProductos.Servicio_Tramite.Bundle,
		  "Opcionales": [],
		  "Promociones": [],
		  "Cliente": {
		    "_id": {
		      "\$oid": vars.clienteTramite.Cliente_Tramite."_id"."\$oid"
		    },
		    "Fecha_Creacion": vars.clienteTramite.Cliente_Tramite.Fecha_Creacion,
		    "Usuario_Creacion": vars.clienteTramite.Cliente_Tramite.Usuario_Creacion,
		    "Fecha_Modificacion": vars.clienteTramite.Cliente_Tramite.Fecha_Actualizacion,
		    "Id_Cuenta_Cliente": vars.clienteTramite.Cliente_Tramite.Id_Cuenta_Cliente,
		    "Tipo_Documento": vars.clienteTramite.Cliente_Tramite.Tipo_Documento,
		    "Numero_Documento": vars.clienteTramite.Cliente_Tramite.Numero_Documento
		  },
		  "Estado": {
		    "Principal": {
		      "Codigo": "2",
		      "Descripcion": "Pendiente",
		      "Fecha": fechaActual
		    },
		    "Pago": {
		      "Codigo": "1",
		      "Descripcion": "Activo",
		      "Fecha": fechaActual
		    },
		    "Fraude": {
		      "Codigo": "1",
		      "Descripcion": "Activo",
		      "Fecha": fechaActual
		    },
		    "Tramite": {
		      "Codigo": "2",
		      "Descripcion": "Pendiente",
		      "Fecha": fechaActual
		    },
		    "Voluntaria": {
		      "Codigo": "1",
		      "Descripcion": "Activo",
		      "Fecha": fechaActual
		    },
		    "RoboPerdida": {
		      "Codigo": "1",
		      "Descripcion": "Activo",
		      "Fecha": fechaActual
		    }
		  },
		  "Id_Cuenta_Facturacion": vars.resultadoProductos.Servicio_Tramite.Id_Cuenta_Facturacion,
		  "Sistema_Origen": {
		    "Id_Sistema_Origen": vars.resultadoProductos.Servicio_Tramite.Id_Cuenta_Servicio,
		    "Sistema_Origen_Nombre": vars.resultadoProductos.Servicio_Tramite.Sistema_Origen
		  },
		  "Id_Direccion_Instalacion": vars.resultadoProductos.Servicio_Tramite.Id_Direccion_Instalacion,
		  "Servicios_Auxiliares": vars.resultadoProductos.Servicio_Tramite.Servicios_Auxiliares,
		  "Clausula_Permanencia": vars.resultadoProductos.Servicio_Tramite.Clausula_Permanencia,
		  "Numero_Conexion_Anterior": vars.resultadoProductos.Servicio_Tramite.Numero_Conexion_Anterior,
		  "Id_SalesForce": vars.resultadoProductos.Servicio_Tramite.Id_SalesForce,
		  "Integration_Id": vars.resultadoProductos.Servicio_Tramite.Integration_Id,
		  "Caracteristica_Servicio": vars.resultadoProductos.Servicio_Tramite.Caracteristica_Servicio,
		  "Is_Pago_Recurrente": vars.resultadoProductos.Servicio_Tramite.Is_Pago_Recurrente,
		  "Promociones_Condicionadas": vars.resultadoProductos.Servicio_Tramite.Promociones_Condicionadas,
		  "Adjuntos": vars.resultadoProductos.Servicio_Tramite.Adjuntos
		}
    ]
  }
},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}
